/**
 * knowledge-gap-tasks.mjs — Generate `- [ ]` tasks from Research Spine evidence
 * (market cycle status, freshness sources, research content candidates) and
 * write them into `04_Human_Notes/Inbox.md` `## Knowledge & Research` section
 * between `<!-- KG-AUTO:START -->` and `<!-- KG-AUTO:END -->` markers.
 *
 * Idempotent: re-runs replace the managed block in place. Human-curated content
 * outside the markers (and elsewhere in the section) is preserved.
 *
 * Flags:
 *   --dry-run        Print what would be written; don't modify Inbox.md
 *   --no-inbox       Skip Inbox write (compute and report counts only)
 *   --max-cycles N   Cap cycle tasks (default: all gap/degraded/stale/partial)
 *   --max-fresh N    Cap freshness tasks (default: 20)
 *   --max-cand N     Cap content candidate tasks (default: 16)
 */

import { existsSync, readFileSync, writeFileSync, statSync } from 'fs';
import { readdir, readFile } from 'fs/promises';
import { join } from 'path';
import { getResearchVaultRoot } from '../lib/config.mjs';
import { parseFrontmatter } from '../lib/frontmatter.mjs';

const KR_HEADING = '## Knowledge & Research';
const MARKER_START = '<!-- KG-AUTO:START -->';
const MARKER_END = '<!-- KG-AUTO:END -->';

const FRESHNESS_DAYS = {
  '15min': 1,
  hourly: 1,
  daily: 2,
  weekly: 10,
  monthly: 40,
  quarterly: 110,
  'on-demand': 14,
};

function freshnessStatus(datePulled, cadence) {
  if (!datePulled) return 'Never';
  const date = new Date(datePulled);
  if (Number.isNaN(date.getTime())) return 'Never';
  const days = Math.floor((Date.now() - date.getTime()) / 86400000);
  const allowed = FRESHNESS_DAYS[cadence] ?? 999;
  if (days <= allowed) return 'Fresh';
  if (days <= allowed * 2) return 'Aging';
  return 'Stale';
}

async function listMd(dir, recursive = false) {
  if (!existsSync(dir)) return [];
  const out = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = join(dir, e.name);
    if (e.isDirectory()) {
      if (recursive) out.push(...(await listMd(p, true)));
    } else if (e.isFile() && e.name.endsWith('.md')) {
      out.push(p);
    }
  }
  return out;
}

async function readFm(path) {
  const text = await readFile(path, 'utf-8');
  const { data } = parseFrontmatter(text);
  return data || {};
}

function safe(v) {
  return String(v ?? '').replace(/[\r\n|]/g, ' ').trim();
}

async function gatherCycleTasks(researchRoot, max) {
  const dir = join(researchRoot, '01_Freshness', 'Market_Cycles');
  const files = await listMd(dir);
  const tasks = [];
  for (const f of files) {
    const fm = await readFm(f);
    if (fm.type !== 'market_cycle_status') continue;
    const coverage = String(fm.coverage_status ?? '').toLowerCase();
    if (!['gap', 'degraded', 'stale', 'partial'].includes(coverage)) continue;
    const layer = safe(fm.cycle_layer) || '<unknown layer>';
    const state = safe(fm.cycle_state) || '—';
    const transition = safe(fm.transition) || '—';
    const missing = safe(fm.missing_inputs) || '—';
    const url = String(fm.obsidian_url ?? '');
    const src = url ? ` ([source](${url}))` : '';
    tasks.push(
      `- [ ] [knowledge-gap/cycle] ${layer} coverage **${coverage}** (state: ${state}, transition: ${transition}) — missing: ${missing}${src}`
    );
  }
  tasks.sort();
  return max ? tasks.slice(0, max) : tasks;
}

async function gatherFreshnessTasks(researchRoot, max) {
  const dir = join(researchRoot, '01_Freshness', 'Sources');
  const files = await listMd(dir);
  const rows = [];
  for (const f of files) {
    const fm = await readFm(f);
    if (fm.type !== 'freshness_item') continue;
    const status = freshnessStatus(fm.date_pulled, fm.cadence);
    if (!['Aging', 'Stale', 'Never'].includes(status)) continue;
    rows.push({
      status,
      domain: safe(fm.domain),
      source: safe(fm.source) || '<unnamed>',
      data_type: safe(fm.data_type) || '—',
      cadence: safe(fm.cadence) || 'unknown',
      datePulled: safe(fm.date_pulled) || '—',
    });
  }
  const order = { Stale: 0, Never: 1, Aging: 2 };
  rows.sort((a, b) =>
    (order[a.status] ?? 9) - (order[b.status] ?? 9)
    || a.domain.localeCompare(b.domain)
    || a.source.localeCompare(b.source)
  );
  const limited = rows.slice(0, max ?? 20);
  return limited.map(r =>
    `- [ ] [knowledge-gap/freshness/${r.status.toLowerCase()}] Refresh **${r.source}** (${r.domain} / ${r.data_type}, cadence: ${r.cadence}) — last pulled: ${r.datePulled}`
  );
}

async function gatherCandidateTasks(researchRoot, max) {
  const dir = join(researchRoot, '03_References', 'Content_Candidates');
  const files = await listMd(dir, true);
  const candidates = [];
  for (const f of files) {
    const fm = await readFm(f);
    if (fm.type !== 'research_content_candidate') continue;
    candidates.push({ mtime: statSync(f).mtimeMs, fm });
  }
  candidates.sort((a, b) => b.mtime - a.mtime);
  const limited = candidates.slice(0, max ?? 16);
  return limited.map(({ fm }) => {
    const title = safe(fm.title) || '<untitled>';
    const topic = safe(fm.topic) || '—';
    const type = safe(fm.content_type) || '—';
    const source = safe(fm.source) || '—';
    const url = String(fm.url ?? '');
    const link = url ? ` ([open](${url}))` : '';
    return `- [ ] [knowledge-gap/candidate] Review **${title}** (${topic} / ${type}) — ${source}${link}`;
  });
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildBlockBody(tasks) {
  const generatedAt = new Date().toISOString();
  return [
    MARKER_START,
    `<!-- Auto-generated ${generatedAt} by knowledge-gap-tasks.mjs. Do not hand-edit between markers — edits will be replaced on next run. -->`,
    '',
    tasks.length
      ? tasks.join('\n')
      : '_(no knowledge-gap tasks — all cycle layers covered, sources fresh, no pending candidates)_',
    '',
    MARKER_END,
  ].join('\n');
}

function replaceManagedBlock(inboxRaw, tasks) {
  const blockBody = buildBlockBody(tasks);
  const blockRe = new RegExp(`${escapeRe(MARKER_START)}[\\s\\S]*?${escapeRe(MARKER_END)}`);
  if (blockRe.test(inboxRaw)) {
    return inboxRaw.replace(blockRe, blockBody);
  }

  const headingIdx = inboxRaw.indexOf(KR_HEADING);
  if (headingIdx < 0) {
    // Section missing — create it under the AUTO-INSERT-ABOVE marker (preferred)
    // or at end of file.
    const sectionBlock =
      `${KR_HEADING}\n\n` +
      'Task format. Auto-tasks between markers are managed by `node run.mjs pull knowledge-gap-tasks`.\n\n' +
      `${blockBody}\n`;
    const insertMarker = '<!-- AUTO-INSERT-ABOVE';
    const idx = inboxRaw.indexOf(insertMarker);
    if (idx >= 0) {
      const before = inboxRaw.slice(0, idx).replace(/\s+$/, '');
      const after = inboxRaw.slice(idx);
      return `${before}\n\n${sectionBlock}\n${after}`;
    }
    return `${inboxRaw.trimEnd()}\n\n${sectionBlock}`;
  }

  // Insert managed block after heading + first paragraph.
  const tail = inboxRaw.slice(headingIdx);
  const blankIdx = tail.search(/\n\s*\n/);
  if (blankIdx < 0) {
    const lineEnd = inboxRaw.indexOf('\n', headingIdx);
    const insertAt = lineEnd < 0 ? inboxRaw.length : lineEnd + 1;
    return `${inboxRaw.slice(0, insertAt)}\n${blockBody}\n${inboxRaw.slice(insertAt)}`;
  }
  const insertAt = headingIdx + blankIdx + 2;
  return `${inboxRaw.slice(0, insertAt)}${blockBody}\n\n${inboxRaw.slice(insertAt)}`;
}

export async function pull(flags = {}) {
  const dryRun = !!(flags['dry-run'] || flags.dryRun);
  const skipInbox = !!(flags['no-inbox'] || flags.noInbox);
  const maxCycles = Number(flags['max-cycles'] ?? flags.maxCycles ?? 0) || null;
  const maxFresh = Number(flags['max-fresh'] ?? flags.maxFresh ?? 20) || null;
  const maxCand = Number(flags['max-cand'] ?? flags.maxCand ?? 16) || null;

  const researchRoot = getResearchVaultRoot();
  const inboxPath = join(researchRoot, '04_Human_Notes', 'Inbox.md');

  const [cycleTasks, freshTasks, candTasks] = await Promise.all([
    gatherCycleTasks(researchRoot, maxCycles),
    gatherFreshnessTasks(researchRoot, maxFresh),
    gatherCandidateTasks(researchRoot, maxCand),
  ]);

  const tasks = [...cycleTasks, ...freshTasks, ...candTasks];
  console.log(
    `knowledge-gap-tasks: cycle=${cycleTasks.length} freshness=${freshTasks.length} candidates=${candTasks.length} total=${tasks.length}`
  );

  if (skipInbox) {
    console.log('--no-inbox: skipping Inbox write.');
    return { source: 'knowledge-gap-tasks', tasks: tasks.length, wrote: false };
  }

  if (!existsSync(inboxPath)) {
    console.warn(`Warning: Inbox.md not found at ${inboxPath} — skipping write.`);
    return { source: 'knowledge-gap-tasks', tasks: tasks.length, wrote: false };
  }

  let inboxRaw = readFileSync(inboxPath, 'utf-8');
  if (inboxRaw.charCodeAt(0) === 0xFEFF) inboxRaw = inboxRaw.slice(1);
  const next = replaceManagedBlock(inboxRaw, tasks);

  if (dryRun) {
    console.log(`[dry-run] would write ${tasks.length} task(s) to ${inboxPath}`);
    if (tasks.length) {
      console.log('---');
      for (const t of tasks.slice(0, 5)) console.log(t);
      if (tasks.length > 5) console.log(`... (${tasks.length - 5} more)`);
    }
    return { source: 'knowledge-gap-tasks', dryRun: true, tasks: tasks.length };
  }

  if (next !== inboxRaw) {
    writeFileSync(inboxPath, next, 'utf-8');
    console.log(`knowledge-gap-tasks: wrote ${tasks.length} task(s) to ${inboxPath}`);
  } else {
    console.log('knowledge-gap-tasks: no changes (block already up to date).');
  }
  return { source: 'knowledge-gap-tasks', tasks: tasks.length, wrote: next !== inboxRaw };
}

